
.status-bar {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  font-family: var(--font-status);
  color: var(--c-ink);
  background-color: var(--c-bg-light);
  border: 1px solid var(--c-line);
  box-shadow: 0 2px 10px rgba(43, 38, 34, 0.12);
  transition: background-color 0.6s ease, color 0.6s ease, border-color 0.6s ease;
}

.status-bar.dark {
  background-color: var(--c-bg-dark);
  color: var(--c-bg-light);
  border-color: var(--c-primary);
}

.header {
  padding: 10px 14px;
  cursor: pointer;
  user-select: none;
}

.title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}

.name {
  font-size: 1.15rem;
  font-weight: bold;
  letter-spacing: 0.08em;
}

.stage {
  font-size: 0.8rem;
  font-weight: bold;
  padding: 2px 8px;
  border: 1px solid var(--c-muted);
  color: var(--c-muted);
  letter-spacing: 0.2em;
  border-radius: 2px;
}

.stage-late {
  border-color: var(--c-primary);
  color: var(--c-primary);
}

.meta-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.78rem;
  color: var(--c-muted);
}

.meta-loc i {
  margin-right: 4px;
}

.meta-hint i {
  margin-left: 2px;
}

.bars {
  padding: 0 14px 10px;
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bar-label {
  font-size: 0.75rem;
  width: 4.5em;
  letter-spacing: 0.1em;
}

.bar-track {
  flex: 1;
  height: 9px;
  border: 1px solid var(--c-line);
  background: rgba(255, 255, 255, 0.35);
  overflow: hidden;
}

.dark .bar-track {
  border-color: var(--c-primary);
  background: rgba(138, 58, 58, 0.12);
}

.bar-fill {
  height: 100%;
  transition: width 0.5s ease, background-color 0.5s ease;
}

.bar-fill.corruption {
  background-color: var(--c-muted);
}

.dark .bar-fill.corruption {
  background-color: var(--c-primary);
}

.bar-fill.dependency {
  background-color: var(--c-accent);
}

.bar-value {
  font-size: 0.75rem;
  width: 2.6em;
  text-align: right;
  font-weight: bold;
}

.detail {
  border-top: 1px solid var(--c-line);
  padding: 10px 14px 12px;
}

.detail-section {
  margin-bottom: 10px;
}

.detail-section:last-child {
  margin-bottom: 0;
}

.detail-head {
  font-size: 0.75rem;
  letter-spacing: 0.2em;
  color: var(--c-muted);
  border-bottom: 1px solid var(--c-line);
  padding-bottom: 4px;
  margin-bottom: 7px;
}

.attire-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 6px;
}

.attire-item {
  border: 1px solid var(--c-line);
  padding: 5px 7px;
  font-size: 0.8rem;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.attire-slot {
  font-size: 0.68rem;
  color: var(--c-muted);
  letter-spacing: 0.1em;
}

.bond-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 6px;
}

.bond-item {
  border: 1px solid var(--c-line);
  padding: 5px 7px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 0.8rem;
  transition: border-color 0.3s ease;
}

.bond-item.bound {
  border-color: var(--c-primary);
}

.bond-slot {
  font-size: 0.68rem;
  color: var(--c-muted);
  letter-spacing: 0.1em;
}

.bond-item.bound .bond-text {
  color: var(--c-primary);
  font-weight: bold;
}

.expand-enter-active,
.expand-leave-active {
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.expand-enter-from,
.expand-leave-to {
  opacity: 0;
  transform: translateY(-4px);
}

@media (max-width: 600px) {
  .attire-grid,
  .bond-grid {
    grid-template-columns: 1fr;
  }
}
